283	    private static boolean isBlank(String value) {
284	        return value == null || value.isBlank();
285	    }
286	
287	    /**
288	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
289	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
290	     */
291	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
292	        "NSW", new int[] {2000, 2099},
293	        "VIC", new int[] {3000, 3099},
294	        "QLD", new int[] {4000, 4099});
295	
296	    /**
297	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
298	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
299	     * present, the value has already passed the 4-digit format check (Bean Validation on the
300	     * request body); this enforces that it falls within the inclusive range for the city's region
301	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
302	     *
303	     * @param postcode the supplied postcode (may be {@code null})
304	     * @param region the owner's locality/region derived from its city
305	     * @throws InvalidPostcodeException if the postcode is out of range for the region
306	     */
307	    private static void validatePostcode(String postcode, String region) {
308	        if (isBlank(postcode)) {
309	            return;
310	        }
311	        int[] range = REGION_POSTCODES.get(region);
312	        if (range == null) {
313	            return;
314	        }
315	        int value;
316	        try {
317	            value = Integer.parseInt(postcode);
318	        }
319	        catch (NumberFormatException e) {
320	            throw new InvalidPostcodeException(postcode);
321	        }
322	        if (value < range[0] || value > range[1]) {
323	            throw new InvalidPostcodeException(postcode);
324	        }
325	    }
326	
327	    /**
328	     * Normalizes a street address into the canonical form stored on and returned for a newly
329	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
330	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
331	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
332	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
333	     * value is what gets persisted, echoed back, and used for every address comparison (household
334	     * duplicate detection and the shared household identifier).
335	     *
336	     * @param rawAddress the address value as supplied by the client
337	     * @return the normalized address (possibly empty, never {@code null})
338	     */
339	    private static String normalizeAddress(String rawAddress) {
340	        if (rawAddress == null) {
341	            return "";
342	        }
343	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
344	        if (collapsed.isEmpty()) {
345	            return "";
346	        }
347	        String[] tokens = collapsed.split(" ");
348	        StringBuilder sb = new StringBuilder(collapsed.length());
349	        for (int i = 0; i < tokens.length; i++) {
350	            String token = tokens[i];
351	            switch (token) {
352	                case "ST" -> token = "STREET";
353	                case "RD" -> token = "ROAD";
354	                case "AVE" -> token = "AVENUE";
355	                default -> { }
356	            }
357	            if (i > 0) {
358	                sb.append(' ');
359	            }
360	            sb.append(token);
361	        }
362	        return sb.toString();
363	    }
364	
365	    /**
366	     * Builds the customer code assigned to a newly created owner. The code is formatted
367	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
368	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
369	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
370	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
371	     * the owner's own region and identity.
372	     *
373	     * @param owner the owner being created, with telephone already normalized and postcode/city set
374	     * @return the customer code to assign
375	     */
376	    private static String customerCodeFor(Owner owner) {
377	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
378	    }
379	
380	    /**
381	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
382	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
383	     * last name.
384	     *
385	     * @param normalizedTelephone the owner's telephone in E.164 form
386	     * @param lastName the owner's last name
387	     * @return the 8-character upper-case hex hash
388	     */
389	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
390	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
391	            + (lastName == null ? "" : lastName);
392	        try {
393	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
394	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
395	            StringBuilder sb = new StringBuilder(digest.length * 2);
396	            for (byte b : digest) {
397	                sb.append(String.format("%02x", b));
398	            }
399	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
400	        }
401	        catch (java.security.NoSuchAlgorithmException e) {
402	            throw new IllegalStateException("SHA-256 not available", e);
403	        }
404	    }
405	
406	    /**
407	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
408	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
409	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
410	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
411	     * the national number must match the country code: {@code +61} requires 9 national digits and
412	     * {@code +1} requires 10.
413	     *
414	     * @param rawTelephone the telephone value as supplied by the client
415	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
416	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
417	     */
418	    private static String normalizeTelephone(String rawTelephone) {
419	        if (rawTelephone == null) {
420	            throw new InvalidTelephoneException(rawTelephone);
421	        }
422	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
423	        String e164;
424	        if (cleaned.startsWith("+")) {
425	            String digits = cleaned.substring(1);
426	            if (!digits.matches("[0-9]+")) {
427	                throw new InvalidTelephoneException(rawTelephone);
428	            }
429	            e164 = "+" + digits;
430	        } else {
431	            if (!cleaned.matches("[0-9]+")) {
432	                throw new InvalidTelephoneException(rawTelephone);
433	            }
434	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
435	            e164 = "+61" + national;
436	        }
437	        int digitCount = e164.length() - 1;
438	        if (digitCount < 8 || digitCount > 15) {
439	            throw new InvalidTelephoneException(rawTelephone);
440	        }
441	        if (e164.startsWith("+61")) {
442	            if (e164.length() - "+61".length() != 9) {
443	                throw new InvalidTelephoneException(rawTelephone);
444	            }
445	        }
446	        else if (e164.startsWith("+1")) {
447	            if (e164.length() - "+1".length() != 10) {
448	                throw new InvalidTelephoneException(rawTelephone);
449	            }
450	        }
451	        return e164;
452	    }
453	
454	    /**
455	     * Determines whether any existing owner already carries the given identity key. The identity key
456	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
457	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
458	     * are equal.
459	     *
460	     * @param identityKey the identity key of the owner being created
461	     * @return {@code true} if another owner already has the same identity key
462	     */
463	    private boolean isIdentityKeyInUse(String identityKey) {
464	        return this.clinicService.findAllOwners().stream()
465	            .map(Owner::getIdentityKey)
466	            .anyMatch(identityKey::equals);
467	    }
468	
469	    /**
470	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
471	     * that shares the same last name (compared case-insensitively, whitespace-collapsed) and the
472	     * same postcode but carries a <em>different</em> telephone. Such a create is not rejected as a
473	     * hard duplicate, but is flagged. An owner with no postcode can never be a soft duplicate. When
474	     * several owners match, the earliest (lowest id) is returned so the result is deterministic.
475	     *
476	     * @param owner the owner being created (telephone already normalized, postcode set)
477	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
478	     */
479	    private Integer possibleDuplicateOf(Owner owner) {
480	        if (isBlank(owner.getPostcode())) {
481	            return null;
482	        }
483	        String normalizedLastName = normalizeIdentity(owner.getLastName());
484	        return this.clinicService.findAllOwners().stream()
485	            .filter(existing -> existing.getId() != null
486	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
487	                && owner.getPostcode().equals(existing.getPostcode())
488	                && !java.util.Objects.equals(owner.getTelephone(), existing.getTelephone()))
489	            .map(Owner::getId)
490	            .min(Integer::compareTo)
491	            .orElse(null);
492	    }
493	
494	    /**
495	     * Counts how many existing owners already share the given first name and last name with the
496	     * owner being created. Both names are compared case-insensitively (after trimming and
497	     * collapsing runs of whitespace). The count reflects the state before the new owner is
498	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
499	     *
500	     * @param firstName the first name of the owner being created
501	     * @param lastName the last name of the owner being created
502	     * @return the number of existing owners sharing the same first and last name
503	     */
504	    private int namesakeCount(String firstName, String lastName) {
505	        String normalizedFirstName = normalizeIdentity(firstName);
506	        String normalizedLastName = normalizeIdentity(lastName);
507	        return (int) this.clinicService.findAllOwners().stream()
508	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
509	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
510	            .count();
511	    }
512	
513	    /**
514	     * Counts how many members the owner being created belongs to in its household, including
515	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
516	     * the new owner is not yet persisted, so its own membership is added to the existing count.
517	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
518	     * household of one.
519	     *
520	     * @param householdId the shared household identifier assigned to the owner being created, or
521	     *                    {@code null} if the owner does not share a household
522	     * @return the number of household members after this create (at least 1)
523	     */
524	    private int householdSizeAfterCreate(String householdId) {
525	        if (householdId == null) {
526	            return 1;
527	        }
528	        long existing = this.clinicService.findAllOwners().stream()
529	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
530	            .count();
531	        return (int) existing + 1;
532	    }
533	
534	    /**
535	     * The maximum number of owners permitted in a single city. Once a city already contains this
536	     * many owners it is considered full and no further owners may be created there.
537	     */
538	    private static final int CITY_CAPACITY = 50;
539	
540	    /**
541	     * Determines whether the given city has already reached its capacity, i.e. already contains
542	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
543	     * collapsing runs of whitespace to a single space and trimming.
544	     *
545	     * @param city the city of the owner being created
546	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
547	     */
548	    private boolean isCityAtCapacity(String city) {
549	        String normalizedCity = normalizeIdentity(city);
550	        long count = this.clinicService.findAllOwners().stream()
551	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
552	            .count();
553	        return count >= CITY_CAPACITY;
554	    }
555	
556	    /**
557	     * The maximum number of owners that may be created on any single day. Once this many owners
558	     * already carry a {@code registrationDate} of the current day, no further owners may be created
559	     * that day.
560	     */
561	    private static final int DAILY_REGISTRATION_LIMIT = 100;
562	
563	    /**
564	     * Determines whether the daily registration limit has already been reached, i.e. whether
565	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
566	     * their {@code registrationDate}.
567	     *
568	     * @param date the current day
569	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
570	     *         registered on the given date
571	     */
572	    /**
573	     * Rolls a registration date forward onto a business day. A date that already falls on a
574	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
575	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
576	     * everything derived from it (the membership number's year segment, the daily create-limit).
577	     *
578	     * @param date the effective registration date (supplied by the client or defaulted to the
579	     *             server's current date)
580	     * @return the same date if it is a weekday, otherwise the following Monday
581	     */
582	    private static LocalDate toBusinessDay(LocalDate date) {
583	        DayOfWeek dayOfWeek = date.getDayOfWeek();
584	        if (dayOfWeek == DayOfWeek.SATURDAY) {
585	            return date.plusDays(2);
586	        }
587	        if (dayOfWeek == DayOfWeek.SUNDAY) {
588	            return date.plusDays(1);
589	        }
590	        return date;
591	    }
592	
593	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
594	        long count = this.clinicService.findAllOwners().stream()
595	            .filter(existing -> date.equals(existing.getRegistrationDate()))
596	            .count();
597	        return count >= DAILY_REGISTRATION_LIMIT;
598	    }
599	
600	    /**
601	     * The number of owners that may be created on a single day before the bulk-signup warning is
602	     * raised. Once <em>more than</em> this many owners already carry the current business day as
603	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
604	     */
605	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
606	
607	    /**
608	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
609	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
610	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
611	     *
612	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
613	     *         registered on today's business day
614	     */
615	    private boolean isBulkSignupWarning() {
616	        LocalDate today = toBusinessDay(LocalDate.now());
617	        long count = this.clinicService.findAllOwners().stream()
618	            .filter(existing -> today.equals(existing.getRegistrationDate()))
619	            .count();
620	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
621	    }
622	
623	    /**
624	     * Back-fills the given household identifier onto every existing member of the household (those
625	     * sharing the same last name and address) that does not yet carry it, so all household members
626	     * share the stable identifier regardless of creation order. The identifier itself is derived
627	     * deterministically by {@link #householdIdFor(String, String)}.
628	     *
629	     * @param lastName the last name of the owner being created
630	     * @param address the address of the owner being created
631	     * @param householdId the stable household identifier assigned to the owner being created
632	     */
633	    private void backfillHousehold(String lastName, String address, String householdId) {
634	        String normalizedLastName = normalizeIdentity(lastName);
635	        String normalizedAddress = normalizeIdentity(address);
636	        for (Owner existing : this.clinicService.findAllOwners()) {
637	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
638	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
639	                && !householdId.equals(existing.getHouseholdId())) {
640	                existing.setHouseholdId(householdId);
641	                this.clinicService.saveOwner(existing);
642	            }
643	        }
644	    }
645	
646	    /**
647	     * Derives the stable household identifier for a given last name and address. The value is the
648	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
649	     * address, so it is stable across calls and identical for every member of the household.
650	     *
651	     * @param lastName the last name of the household
652	     * @param address the address of the household
653	     * @return the stable household identifier
654	     */
655	    private static String householdIdFor(String lastName, String address) {
656	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
657	        try {
658	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
659	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
660	            StringBuilder sb = new StringBuilder(digest.length * 2);
661	            for (byte b : digest) {
662	                sb.append(String.format("%02x", b));
663	            }
664	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
665	        }
666	        catch (java.security.NoSuchAlgorithmException e) {
667	            throw new IllegalStateException("SHA-256 not available", e);
668	        }
669	    }
670	
671	    /**
672	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
673	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
674	     * single space, and the result is lower-cased.
675	     *
676	     * @param value the raw field value
677	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
678	     */
679	    private static String normalizeIdentity(String value) {
680	        if (value == null) {
681	            return "";
682	        }
683	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
684	    }
685	}
