28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: a leading '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "birth_date", columnDefinition = "DATE")
60	    private LocalDate birthDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "household_size")
72	    private Integer householdSize;
73	
74	    @Column(name = "postcode")
75	    private String postcode;
76	
77	    @Column(name = "possible_duplicate")
78	    private Boolean possibleDuplicate;
79	
80	    @Column(name = "possible_duplicate_of")
81	    private Integer possibleDuplicateOf;
82	
83	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
84	    private Set<Pet> pets;
85	
86	    public String getAddress() {
87	        return this.address;
88	    }
89	
90	    public void setAddress(String address) {
91	        this.address = address;
92	    }
93	
94	    public String getCity() {
95	        return this.city;
96	    }
97	
98	    public void setCity(String city) {
99	        this.city = city;
100	    }
101	
102	    public String getTelephone() {
103	        return this.telephone;
104	    }
105	
106	    public void setTelephone(String telephone) {
107	        this.telephone = telephone;
108	    }
109	
110	    public String getEmail() {
111	        return this.email;
112	    }
113	
114	    /**
115	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
116	     * {@code null} value (email omitted) is preserved as {@code null}.
117	     */
118	    public void setEmail(String email) {
119	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
120	    }
121	
122	    public LocalDate getRegistrationDate() {
123	        return this.registrationDate;
124	    }
125	
126	    public void setRegistrationDate(LocalDate registrationDate) {
127	        this.registrationDate = registrationDate;
128	    }
129	
130	    public LocalDate getBirthDate() {
131	        return this.birthDate;
132	    }
133	
134	    public void setBirthDate(LocalDate birthDate) {
135	        this.birthDate = birthDate;
136	    }
137	
138	    /**
139	     * The owner's age band, derived from {@link #birthDate} measured against the
140	     * {@link #registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64
141	     * inclusive, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
142	     * supplied, so the field is simply absent from the response.
143	     */
144	    @Transient
145	    public String getAgeBand() {
146	        if (this.birthDate == null) {
147	            return null;
148	        }
149	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
150	        int age = java.time.Period.between(this.birthDate, reference).getYears();
151	        if (age < 18) {
152	            return "MINOR";
153	        }
154	        if (age < 65) {
155	            return "ADULT";
156	        }
157	        return "SENIOR";
158	    }
159	
160	    public String getCustomerCode() {
161	        return this.customerCode;
162	    }
163	
164	    public void setCustomerCode(String customerCode) {
165	        this.customerCode = customerCode;
166	    }
167	
168	    /**
169	     * A single Luhn check digit (0-9) computed over the digits contained in the
170	     * {@link #customerCode}. Non-digit characters in the code are ignored; the standard Luhn
171	     * algorithm doubles every second digit from the right (subtracting 9 when the result exceeds
172	     * 9) and the check digit is {@code (10 - (sum % 10)) % 10}. {@code null} until a customer code
173	     * is assigned.
174	     */
175	    @Transient
176	    public Integer getCheckDigit() {
177	        if (this.customerCode == null) {
178	            return null;
179	        }
180	        int sum = 0;
181	        boolean dbl = true;
182	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
183	            char c = this.customerCode.charAt(i);
184	            if (c < '0' || c > '9') {
185	                continue;
186	            }
187	            int d = c - '0';
188	            if (dbl) {
189	                d *= 2;
190	                if (d > 9) {
191	                    d -= 9;
192	                }
193	            }
194	            sum += d;
195	            dbl = !dbl;
196	        }
197	        return (10 - (sum % 10)) % 10;
198	    }
199	
200	    /**
201	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where {@code YY} is
202	     * the last two digits of the {@code registrationDate} year (e.g. {@code NSW-1A2B3C4D-M26}).
203	     * Derived from the owner's own fields; {@code null} until both are assigned.
204	     */
205	    @Transient
206	    public String getMembershipNumber() {
207	        if (this.customerCode == null || this.registrationDate == null) {
208	            return null;
209	        }
210	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
211	    }
212	
213	    /**
214	     * The owner's membership level, a number from 1 to 3 derived from the owner's own fields as
215	     * captured at creation time. It starts at 1, gains 1 when an email is present, gains a further
216	     * 1 when the owner has no namesakes ({@code namesakeCount} is 0), and is capped at 3. Level 4
217	     * is reserved for tenure and is never produced here.
218	     */
219	    @Transient
220	    public Integer getMembershipLevel() {
221	        int level = 1;
222	        boolean hasEmail = this.email != null && !this.email.isBlank();
223	        if (hasEmail) {
224	            level++;
225	        }
226	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
227	        if (noNamesakes) {
228	            level++;
229	        }
230	        return Math.min(level, 3);
231	    }
232	
233	    /** City -> canonical region for the {@code region} derivation. */
234	    private static final Map<String, String> CITY_REGION = Map.of(
235	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
236	
237	    /** Region -> inclusive 4-digit postcode range {low, high} for the {@code region} derivation. */
238	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
239	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
240	
241	    /**
242	     * The region code that forms the {@code REGION} segment of the {@link #customerCode}, derived
243	     * by looking up the region by {@link #postcode} range first (NSW 2000-2099, VIC 3000-3099,
244	     * QLD 4000-4099), and only falling back to the fixed city-to-region table (Sydney->NSW,
245	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range. Returns
246	     * {@code UNKNOWN} when neither source resolves a region.
247	     */
248	    @Transient
249	    public String getRegion() {
250	        String region = regionForPostcode(this.postcode);
251	        if (region != null) {
252	            return region;
253	        }
254	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
255	    }
256	
257	    /**
258	     * The owner's locality: the {@code REGION} segment of its {@link #customerCode} (everything
259	     * before the first {@code '-'}). Because the customer code is {@code <REGION>-<HASH8>} with
260	     * {@code REGION} derived from the postcode, the locality now simply reads that region back off
261	     * the identity. Returns {@code UNKNOWN} until a customer code is assigned.
262	     */
263	    @Transient
264	    public String getLocality() {
265	        if (this.customerCode == null) {
266	            return "UNKNOWN";
267	        }
268	        int dash = this.customerCode.indexOf('-');
269	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
270	    }
271	
272	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
273	    private static String regionForPostcode(String postcode) {
274	        if (postcode == null) {
275	            return null;
276	        }
277	        int value;
278	        try {
279	            value = Integer.parseInt(postcode.trim());
280	        }
281	        catch (NumberFormatException ex) {
282	            return null;
283	        }
284	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
285	            int[] range = entry.getValue();
286	            if (value >= range[0] && value <= range[1]) {
287	                return entry.getKey();
288	            }
289	        }
290	        return null;
291	    }
292	
293	    /**
294	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
295	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
296	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
297	     * the household segment is the {@code householdId} (empty when the owner does not share a
298	     * household). Two owners are duplicates only when their whole identity keys are equal.
299	     */
300	    @Transient
301	    public String getIdentityKey() {
302	        String telephonePart = this.telephone == null ? "" : this.telephone;
303	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
304	        String householdPart = this.householdId == null ? "" : this.householdId;
305	        return telephonePart + "|" + emailPart + "|" + householdPart;
306	    }
