368	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
369	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
370	        return Collections.unmodifiableList(sortedPets);
