392	    /**
393	     * Return the Pet with the given name, or null if none found for this Owner.
394	     *
395	     * @param name to test
396	     * @return true if pet name is already in use
397	     */
398	    public Pet getPet(String name, boolean ignoreNew) {
399	        name = name.toLowerCase();
400	        for (Pet pet : getPetsInternal()) {
401	            if (!ignoreNew || !pet.isNew()) {
402	                String compName = pet.getName();
403	                compName = compName.toLowerCase();
404	                if (compName.equals(name)) {
405	                    return pet;
406	                }
407	            }
408	        }
409	        return null;
410	    }
